import { assert, assertEmptyRest, assertUint8AnySize, assertUint8 } from './assertUint8.mjs'

export function aesInitCheck(mode, key, usage) {
  assert(mode === 'CBC' || mode === 'CTR' || mode === 'GCM', 'Unexpected AES mode')
  assertUint8AnySize(key, 'key')
  assert(key.length === 16 || key.length === 24 || key.length === 32, 'Invalid key size')
  if (usage !== undefined) assert(usage === 'encrypt' || usage === 'decrypt')

  // Deprecations, targeting only CI for now
  if (globalThis.process?.env?.CI) {
    assert(key.length !== 24, '192-bit AES is deprecated and will soon be removed')
    // TODO: deprecate CTR
  }
}

export function aesParamsCheck(mode, nonce, additionalData) {
  if (mode !== 'GCM') assert(additionalData === undefined)
  assertUint8(nonce, mode === 'GCM' ? 12 : 16, 'nonce')
}

export function aesMethods(aes) {
  return {
    async encryptCBC({ key, nonce, data, format, ...rest }) {
      assertEmptyRest(rest)
      const { encrypt } = await aes('CBC', key, 'encrypt')
      return encrypt({ data, nonce, format })
    },

    async decryptCBC({ key, nonce, data, format, ...rest }) {
      assertEmptyRest(rest)
      const { decrypt } = await aes('CBC', key, 'decrypt')
      return decrypt({ data, nonce, format })
    },

    async encryptCTR({ key, nonce, data, format, ...rest }) {
      assertEmptyRest(rest)
      const { encrypt } = await aes('CTR', key, 'encrypt')
      return encrypt({ data, nonce, format })
    },

    async decryptCTR({ key, nonce, data, format, ...rest }) {
      assertEmptyRest(rest)
      const { decrypt } = await aes('CTR', key, 'decrypt')
      return decrypt({ data, nonce, format })
    },

    async encryptGCM({ key, nonce, data, format, additionalData, ...rest }) {
      assertEmptyRest(rest)
      const { encrypt } = await aes('GCM', key, 'encrypt')
      return encrypt({ data, nonce, format, additionalData })
    },

    async decryptGCM({ key, nonce, data, format, additionalData, ...rest }) {
      assertEmptyRest(rest)
      const { decrypt } = await aes('GCM', key, 'decrypt')
      return decrypt({ data, nonce, format, additionalData })
    },
  }
}
